mapper.sql:
SELECT rr.report_id AS reviewId, pr.project_report_id AS projectReportId, CAST(NULL AS NUMBER(19)) AS teamReportId, CAST(NULL AS NUMBER(19)) AS dailyReportId, p.project_id AS projectId, CAST(NULL AS NUMBER(19)) AS taskId, CAST(NULL AS NUMBER(19)) AS subTaskId, pr.project_member_id AS projectMemberId, 1 AS reportCategory, p.subject AS projectName, CAST(NULL AS VARCHAR2(200)) AS taskName, pr.title AS reportTitle, pr.content AS content, md.name AS authorName, TO_CHAR(NVL(pr.report_date, pr.created), 'YYYY-MM-DD HH24:MI') AS createdDate, pr.progress AS progress, rr.status AS reviewStatus, rr.review AS reviewComment, rr.reject AS rejectReason, TO_CHAR(rr.reviewed, 'YYYY-MM-DD HH24:MI') AS reviewedDate, pm.role AS role, '프로젝트 보고서' AS reportTypeName FROM project_reports pr JOIN projects p ON p.project_id = pr.project_id JOIN project_members pm ON pm.project_member_id = pr.project_member_id JOIN workspace_members wm ON wm.workspace_member_id = pm.workspace_member_id JOIN member_details md ON md.member_id = wm.member_id LEFT JOIN report_reviews rr ON rr.project_report_id = pr.project_report_id AND rr.category = 1 WHERE p.deleted IS NULL AND pr.project_member_id IS NOT NULL AND p.project_id = #{projectId} AND p.workspace_id = #{workspaceId}
UNION ALL
SELECT rr.report_id AS reviewId, CAST(NULL AS NUMBER(19)) AS projectReportId, tr.team_report_id AS teamReportId, CAST(NULL AS NUMBER(19)) AS dailyReportId, p.project_id AS projectId, t.task_id AS taskId, CAST(NULL AS NUMBER(19)) AS subTaskId, tr.project_member_id AS projectMemberId, 2 AS reportCategory, p.subject AS projectName, t.title AS taskName, tr.title AS reportTitle, tr.content AS content, md.name AS authorName, TO_CHAR(tr.created, 'YYYY-MM-DD HH24:MI') AS createdDate, tr.progress AS progress, rr.status AS reviewStatus, rr.review AS reviewComment, rr.reject AS rejectReason, TO_CHAR(rr.reviewed, 'YYYY-MM-DD HH24:MI') AS reviewedDate, pm.role AS role, '업무 보고서' AS reportTypeName FROM team_reports tr JOIN tasks t ON t.task_id = tr.task_id JOIN projects p ON p.project_id = tr.project_id JOIN project_members pm ON pm.project_member_id = tr.project_member_id JOIN workspace_members wm ON wm.workspace_member_id = pm.workspace_member_id JOIN member_details md ON md.member_id = wm.member_id LEFT JOIN report_reviews rr ON rr.team_report_id = tr.team_report_id AND rr.category = 2 WHERE tr.deleted IS NULL AND t.deleted IS NULL AND p.deleted IS NULL AND p.project_id = #{projectId} AND p.workspace_id = #{workspaceId}
UNION ALL
SELECT rr.report_id AS reviewId, CAST(NULL AS NUMBER(19)) AS projectReportId, CAST(NULL AS NUMBER(19)) AS teamReportId, dr.daily_report_id AS dailyReportId, p.project_id AS projectId, t.task_id AS taskId, st.sub_task_id AS subTaskId, dr.project_member_id AS projectMemberId, 3 AS reportCategory, p.subject AS projectName, t.title AS taskName, '일일 보고서' AS reportTitle, dr.content AS content, md.name AS authorName, TO_CHAR(NVL(dr.report_date, dr.created), 'YYYY-MM-DD HH24:MI') AS createdDate, dr.progress AS progress, rr.status AS reviewStatus, rr.review AS reviewComment, rr.reject AS rejectReason, TO_CHAR(rr.reviewed, 'YYYY-MM-DD HH24:MI') AS reviewedDate, pm.role AS role, '일일 보고서' AS reportTypeName FROM daily_reports dr JOIN sub_tasks st ON st.sub_task_id = dr.sub_task_id JOIN tasks t ON t.task_id = st.task_id JOIN projects p ON p.project_id = st.project_id JOIN project_members pm ON pm.project_member_id = dr.project_member_id JOIN workspace_members wm ON wm.workspace_member_id = pm.workspace_member_id JOIN member_details md ON md.member_id = wm.member_id LEFT JOIN report_reviews rr ON rr.daily_report_id = dr.daily_report_id AND rr.category = 3 WHERE dr.deleted IS NULL AND st.deleted IS NULL AND t.deleted IS NULL AND p.deleted IS NULL AND p.project_id = #{projectId} AND p.workspace_id = #{workspaceId}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rowNum, R.* FROM (
    SELECT U.* FROM (  ) U

         AND U.reportCategory = #{reportCategory} 
         AND U.reviewStatus = #{reviewStatus} 

            AND (U.projectName LIKE '%' || #{keyword} || '%' OR U.taskName LIKE '%' || #{keyword} || '%' OR U.reportTitle LIKE '%' || #{keyword} || '%' OR DBMS_LOB.INSTR(U.content, #{keyword}) > 0 OR U.authorName LIKE '%' || #{keyword} || '%')


    ORDER BY U.createdDate DESC, U.reviewId DESC
) R WHERE ROWNUM <= #{end} ) WHERE rowNum >= #{start}

SELECT COUNT(*) FROM ( SELECT U.* FROM (  ) U

         AND U.reportCategory = #{reportCategory} 
         AND U.reviewStatus = #{reviewStatus} 

            AND (U.projectName LIKE '%' || #{keyword} || '%' OR U.taskName LIKE '%' || #{keyword} || '%' OR U.reportTitle LIKE '%' || #{keyword} || '%' OR DBMS_LOB.INSTR(U.content, #{keyword}) > 0 OR U.authorName LIKE '%' || #{keyword} || '%')


)
